namespace sv_9f92fb754c114a1c934d337a9984d5a7.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_9f92fb754c114a1c934d337a9984d5a7.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

<!-- Step Indicator Bar -->
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger mt-3">@ErrorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (CurrentStep == 0)
{
    <div class="form-section">
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="FullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="Email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="Phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <input type="text" class="form-control" @bind="Address" />
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsLoading">
                @if (IsLoading) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (CurrentStep == 1)
{
    <div class="form-section">
        <h3>Work History</h3>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Position @(index + 1)</h5>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Company Name *</label>
                    <input type="text" class="form-control" value="@WorkEntries[index].Company"
                           @onchange="(e) => UpdateWorkEntry(index, we => we.Company = e.Value?.ToString() ?? "")" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" value="@WorkEntries[index].Title"
                           @onchange="(e) => UpdateWorkEntry(index, we => we.Title = e.Value?.ToString() ?? "")" />
                </div>
                <div class="row mb-3">
                    <div class="col-md-4">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" value="@WorkEntries[index].StartDate.ToString("yyyy-MM-dd")"
                               @onchange="(e) => UpdateWorkEntryStartDate(index, e.Value?.ToString())" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")"
                               disabled="@WorkEntries[index].IsCurrent"
                               @onchange="(e) => UpdateWorkEntryEndDate(index, e.Value?.ToString())" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" checked="@WorkEntries[index].IsCurrent"
                                   @onchange="(e) => UpdateWorkEntryCurrent(index, (bool)(e.Value ?? false))" />
                            <label class="form-check-label">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-3">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="3" value="@WorkEntries[index].Description"
                              @onchange="(e) => UpdateWorkEntry(index, we => we.Description = e.Value?.ToString() ?? "")"></textarea>
                </div>
            </div>
        }
        <button class="btn btn-outline-primary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </div>
}

<!-- Step 3: References -->
@if (CurrentStep == 2)
{
    <div class="form-section">
        <h3>References</h3>
        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5>Reference @(index + 1)</h5>
                    @if (References.Count > 2)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="mb-3">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" value="@References[index].Name"
                           @onchange="(e) => UpdateReference(index, r => r.Name = e.Value?.ToString() ?? "")" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" value="@References[index].Relationship"
                           @onchange="(e) => UpdateReference(index, r => r.Relationship = e.Value?.ToString() ?? "")" />
                </div>
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label">Email *</label>
                        <input type="email" class="form-control" value="@References[index].Email"
                               @onchange="(e) => UpdateReference(index, r => r.Email = e.Value?.ToString() ?? "")" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone *</label>
                        <input type="tel" class="form-control" value="@References[index].Phone"
                               @onchange="(e) => UpdateReference(index, r => r.Phone = e.Value?.ToString() ?? "")" />
                    </div>
                </div>
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn btn-outline-primary mb-3" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
        </div>
    </div>
}

<!-- Step 4: Cover Letter -->
@if (CurrentStep == 3)
{
    <div class="form-section">
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="12" maxlength="2000" @bind="CoverLetter" @bind:event="oninput"></textarea>
            <div class="form-text text-end">@CoverLetter.Length / 2000 characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
        </div>
    </div>
}

<!-- Step 5: Review & Submit -->
@if (CurrentStep == 4)
{
    @if (IsSubmitted)
    {
        <div class="form-section text-center">
            <h3 class="text-success">Application Submitted Successfully!</h3>
            <p class="fs-5">Your application ID is: <strong>@SubmittedApplicationId</strong></p>
            <p>Thank you for your application. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="form-section">
            <h3>Review & Submit</h3>

            <!-- Personal Info Summary -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(0)">Edit</a>
                </div>
                <p><strong>Name:</strong> @FullName</p>
                <p><strong>Email:</strong> @Email</p>
                <p><strong>Phone:</strong> @Phone</p>
                <p><strong>Address:</strong> @Address</p>
            </div>

            <!-- Work History Summary -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(1)">Edit</a>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-2 border-start border-3">
                        <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
                        <p class="mb-1 text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </p>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <!-- References Summary -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(2)">Edit</a>
                </div>
                @foreach (var reference in References)
                {
                    <div class="mb-2 ps-2 border-start border-3">
                        <p class="mb-1"><strong>@reference.Name</strong> (@reference.Relationship)</p>
                        <p class="mb-0 text-muted">@reference.Email | @reference.Phone</p>
                    </div>
                }
            </div>

            <!-- Cover Letter Summary -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick="() => NavigateToStep(3)">Edit</a>
                </div>
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsLoading">
                    @if (IsLoading) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                </button>
            </div>
        </div>
    }
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private int HighestCompletedStep { get; set; } = -1;
    private bool IsLoading { get; set; }
    private bool IsSubmitted { get; set; }
    private int SubmittedApplicationId { get; set; }
    private string ErrorMessage { get; set; } = "";

    // Step 1: Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetter { get; set; } = "";

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex <= HighestCompletedStep) return "completed";
        return "dimmed";
    }

    private void NavigateToStep(int stepIndex)
    {
        if (stepIndex <= HighestCompletedStep || stepIndex == CurrentStep)
        {
            ErrorMessage = "";
            CurrentStep = stepIndex;
        }
    }

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = "";

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsLoading = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
            if (!isValidEmail)
            {
                ErrorMessage = "The email address is not valid. Please enter a valid email.";
                return;
            }
            AdvanceStep();
        }
        finally
        {
            IsLoading = false;
        }
    }

    private void NextFromWorkHistory()
    {
        ErrorMessage = "";

        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ErrorMessage = "Please fill in company name, job title, and start date for all positions.";
                return;
            }
        }

        AdvanceStep();
    }

    private void NextFromReferences()
    {
        ErrorMessage = "";

        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                ErrorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }

        AdvanceStep();
    }

    private void NextFromCoverLetter()
    {
        ErrorMessage = "";

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }

        AdvanceStep();
    }

    private void AdvanceStep()
    {
        if (CurrentStep > HighestCompletedStep)
            HighestCompletedStep = CurrentStep;
        CurrentStep++;
    }

    private void PreviousStep()
    {
        ErrorMessage = "";
        if (CurrentStep > 0)
            CurrentStep--;
    }

    private async Task SubmitApplication()
    {
        IsLoading = true;
        ErrorMessage = "";

        try
        {
            var personalInfo = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(we =>
                new WorkEntry(we.Company, we.Title, we.StartDate, we.IsCurrent ? null : we.EndDate, we.Description)).ToList());
            var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personalInfo, workHistory, references, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"An error occurred while submitting: {ex.Message}";
        }
        finally
        {
            IsLoading = false;
        }
    }

    // Work Entry helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1)
            WorkEntries.RemoveAt(index);
    }

    private void UpdateWorkEntry(int index, Action<WorkEntryModel> update) => update(WorkEntries[index]);

    private void UpdateWorkEntryStartDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            WorkEntries[index].StartDate = date;
    }

    private void UpdateWorkEntryEndDate(int index, string? value)
    {
        if (DateTime.TryParse(value, out var date))
            WorkEntries[index].EndDate = date;
    }

    private void UpdateWorkEntryCurrent(int index, bool isCurrent)
    {
        WorkEntries[index].IsCurrent = isCurrent;
        if (isCurrent)
            WorkEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, Action<ReferenceModel> update) => update(References[index]);

    // Mutable models for form binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 1.5rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.25rem;
    text-align: center;
    color: #6c757d;
}

.step.active .step-label {
