272. @code {
273.     private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
274. 
275.     private int CurrentStep { get; set; }
276.     private int HighestCompletedStep { get; set; } = -1;
277.     private bool IsLoading { get; set; }
278.     private bool IsSubmitted { get; set; }
279.     private int SubmittedApplicationId { get; set; }
280.     private string ErrorMessage { get; set; } = "";
281. 
282.     // Step 1: Personal Info
283.     private string FullName { get; set; } = "";
284.     private string Email { get; set; } = "";
285.     private string Phone { get; set; } = "";
286.     private string Address { get; set; } = "";
287. 
288.     // Step 2: Work History
289.     private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
290. 
291.     // Step 3: References
292.     private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };
293. 
294.     // Step 4: Cover Letter
295.     private string CoverLetter { get; set; } = "";
296. 
297.     private string GetStepClass(int stepIndex)
298.     {
299.         if (stepIndex == CurrentStep) return "active";
300.         if (stepIndex <= HighestCompletedStep) return "completed";
301.         return "dimmed";
302.     }
303. 
304.     private void NavigateToStep(int stepIndex)
305.     {
306.         if (stepIndex <= HighestCompletedStep || stepIndex == CurrentStep)
307.         {
308.             ErrorMessage = "";
309.             CurrentStep = stepIndex;
310.         }
311.     }
312. 
313.     private async Task NextFromPersonalInfo()
314.     {
315.         ErrorMessage = "";
316. 
317.         if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
318.             string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
319.         {
320.             ErrorMessage = "Please fill in all required fields.";
321.             return;
322.         }
323. 
324.         IsLoading = true;
325.         try
326.         {
327.             var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
328.             if (!isValidEmail)
329.             {
330.                 ErrorMessage = "The email address is not valid. Please enter a valid email.";
331.                 return;
332.             }
333.             AdvanceStep();
334.         }
335.         finally
336.         {
337.             IsLoading = false;
338.         }
339.     }
340. 
341.     private void NextFromWorkHistory()
342.     {
343.         ErrorMessage = "";
344. 
345.         foreach (var entry in WorkEntries)
346.         {
347.             if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
348.                 entry.StartDate == default)
349.             {
350.                 ErrorMessage = "Please fill in company name, job title, and start date for all positions.";
351.                 return;
352.             }
353.         }
354. 
355.         AdvanceStep();
356.     }
357. 
358.     private void NextFromReferences()
359.     {
360.         ErrorMessage = "";
361. 
362.         foreach (var reference in References)
363.         {
364.             if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
365.                 string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
366.             {
367.                 ErrorMessage = "Please fill in all fields for each reference.";
368.                 return;
369.             }
370.         }
371. 
372.         AdvanceStep();
373.     }
374. 
375.     private void NextFromCoverLetter()
376.     {
377.         ErrorMessage = "";
378. 
379.         if (string.IsNullOrWhiteSpace(CoverLetter))
380.         {
381.             ErrorMessage = "Please write a cover letter.";
382.             return;
383.         }
384. 
385.         AdvanceStep();
386.     }
387. 
388.     private void AdvanceStep()
389.     {
390.         if (CurrentStep > HighestCompletedStep)
391.             HighestCompletedStep = CurrentStep;
392.         CurrentStep++;
393.     }
394. 
395.     private void PreviousStep()
396.     {
397.         ErrorMessage = "";
398.         if (CurrentStep > 0)
399.             CurrentStep--;
400.     }
401. 
402.     private async Task SubmitApplication()
403.     {
404.         IsLoading = true;
405.         ErrorMessage = "";
406. 
407.         try
408.         {
409.             var personalInfo = new PersonalInfo(FullName, Email, Phone, Address);
410.             var workHistory = new WorkHistory(WorkEntries.Select(we =>
411.                 new WorkEntry(we.Company, we.Title, we.StartDate, we.IsCurrent ? null : we.EndDate, we.Description)).ToList());
412.             var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
413.             var application = new JobApplication(personalInfo, workHistory, references, CoverLetter);
414. 
415.             SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
416.             IsSubmitted = true;
417.         }
418.         catch (Exception ex)
419.         {
420.             ErrorMessage = $"An error occurred while submitting: {ex.Message}";
421.         }
422.         finally
423.         {
424.             IsLoading = false;
425.         }
426.     }
427. 
428.     // Work Entry helpers
429.     private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
430. 
431.     private void RemoveWorkEntry(int index)
432.     {
433.         if (WorkEntries.Count > 1)
434.             WorkEntries.RemoveAt(index);
435.     }
436. 
437.     // Reference helpers
438.     private void AddReference()
439.     {
440.         if (References.Count < 3)
441.             References.Add(new ReferenceModel());
442.     }
443. 
444.     private void RemoveReference(int index)
445.     {
446.         if (References.Count > 2)
447.             References.RemoveAt(index);
448.     }
449. 
