451.     private class WorkEntryModel
452.     {
453.         public string Company { get; set; } = "";
454.         public string Title { get; set; } = "";
455.         public DateTime StartDate { get; set; }
456.         public DateTime? EndDate { get; set; }
457.         public bool IsCurrent { get; set; }
458.         public string Description { get; set; } = "";
459.     }
460. 
461.     private class ReferenceModel
462.     {
463.         public string Name { get; set; } = "";
464.         public string Relationship { get; set; } = "";
465.         public string Email { get; set; } = "";
466.         public string Phone { get; set; } = "";
467.     }
468. }
